shader:
@group(0) @binding(0) var detail: texture_3d<f32>;
@group(0) @binding(1) var supportR8: texture_3d<f32>;
@group(0) @binding(2) var detailSampler: sampler;
@group(0) @binding(3) var<storage,read> positions: array<vec4<f32>>;
@group(0) @binding(4) var<storage,read_write> results: array<vec2<f32>>;
@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) id:vec3<u32>){
  if(id.x>=arrayLength(&positions)){return;}
  let referenceCoord=positions[id.x].xyz;
  let maskInset=vec3<f32>(0.5)/vec3<f32>(textureDimensions(detail,0));
  let a=textureSampleLevel(detail,detailSampler,clamp(referenceCoord,maskInset,vec3<f32>(1.0)-maskInset),0.0).a;
  let r=textureSampleLevel(supportR8,detailSampler,clamp(referenceCoord,maskInset,vec3<f32>(1.0)-maskInset),0.0).r;
  results[id.x]=vec2<f32>(a,r);
}
